INSERT INTO collection_pages VALUES('3c6466967e39def5a2fbe4cbd84a72ba962e8b6aa236a991b4ca9c18ad35d72d','179596e0ac3e7a16f12160af7df06f4c7c98d9410243da5ef4fb333a2f6fc2a1','{"hasNext":false,"items":[{"author":{"account":null,"email":"ramazancesur@192.168.1.110","name":"Ramazan CESUR"},"authoredDate":"2026-03-26T15:34:02Z","committedDate":"2026-03-26T15:34:02Z","committer":{"account":null,"email":"ramazancesur@192.168.1.110","name":"Ramazan CESUR"},"observedAt":"2026-10-08T22:22:48.206Z","repositoryId":1192732462,"sha":"7430a477d32db9cbeff68a2db934ca055bbc04ad"}],"observedAt":"2026-10-08T22:22:48.206Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/ramazancesur/microservice_sample/commits/7430a477d32db9cbeff68a2db934ca055bbc04ad/comments","commit":{"author":{"date":"2026-03-26T15:34:02Z","email":"ramazancesur@192.168.1.110","name":"Ramazan CESUR"},"comment_count":0,"committer":{"date":"2026-03-26T15:34:02Z","email":"ramazancesur@192.168.1.110","name":"Ramazan CESUR"},"message":"feat: banking microservice platform - initial release\n\nBackend: Java 21, Spring Boot 3.3.4, Maven multi-module, Clean Architecture\n- customer-service: CRUD + keyword search (name/email)\n- account-service: account management + account number search\n- ledger-service: double-entry accounting, balance & movements\n- payment-service: idempotent payment processing\n- api-gateway: Spring Cloud Gateway with CORS\n\nFrontend: React 18, TypeScript, Vite 5, Module Federation\n- shell: host app with MUI theme, sidebar, routing\n- remote-customers: customer list with search\n- remote-accounts: account list with customer autocomplete\n- remote-payments: payment form with account autocomplete\n- remote-ledger: balance & movements with account search\n\nInfrastructure:\n- PostgreSQL 16 per service (Flyway migrations)\n- ELK Stack (Elasticsearch, Logstash, Kibana, Filebeat)\n- Docker Compose orchestration\n\nMade-with: Cursor","tree":{"sha":"ade38163a5a3d7e17739cc464b8aa53454eb3057","url":"https://api.github.com/repos/ramazancesur/microservice_sample/git/trees/ade38163a5a3d7e17739cc464b8aa53454eb3057"},"url":"https://api.github.com/repos/ramazancesur/microservice_sample/git/commits/7430a477d32db9cbeff68a2db934ca055bbc04ad","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/ramazancesur/microservice_sample/commit/7430a477d32db9cbeff68a2db934ca055bbc04ad","node_id":"C_kwDORxenLtoAKDc0MzBhNDc3ZDMyZGI5Y2JlZmY2OGEyZGI5MzRjYTA1NWJiYzA0YWQ","parents":[],"sha":"7430a477d32db9cbeff68a2db934ca055bbc04ad","url":"https://api.github.com/repos/ramazancesur/microservice_sample/commits/7430a477d32db9cbeff68a2db934ca055bbc04ad"}],"requestUrl":"https://api.github.com/repos/ramazancesur/microservice_sample/commits?per_page=100&page=1&sha=7430a477d32db9cbeff68a2db934ca055bbc04ad&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T15%3A41%3A43.510Z"}');
